// Shared node-registration step -- the v14 successor to v13's register-intention-node.json
// (mints process_id the same way, same global counter id scheme), generalized so both
// context-update.json's single-match path and batch-processing.json's per-record path call
// this one implementation instead of each carrying their own copy.
//
// Processes $input.all() as ONE sequential pass, not one node id per input item -- confirmed
// live (2026-08-15 probe) that Execute Workflow, given N items and no special options, calls
// this sub-workflow exactly ONCE with all N, so this is the only place that can safely see
// every registration in the same turn: n8n's own splitInBatches does NOT thread mutations
// from one loop iteration to the next (also confirmed live), so any caller trying to
// register one node per loop iteration would have every iteration compute newNodeId from
// the same stale count and collide. A single caller normally sends exactly one item
// (context-update.json's single-match path); this still works identically since the loop
// below just runs once.
const items = $input.all().map((it) => it.json);
let intentionNodes = items[0]?.intention_nodes || {};
const registered = items.map((data) => {
  const processId = data.process_definition?.id ?? data.process_definition?.slug ?? null;
  const newNodeId = `${processId}#${Object.keys(intentionNodes).length}`;
  const status = data.status ?? 'active';
  // A node minted straight into 'completed' (the common batch-processing.json case --
  // most records in a batch register already-done, never touching form-filling or SAP
  // execution again) never needs its full schema again -- only .name, for display in the
  // Intention Graph / general-inquiry context. Storing the whole process_definition here
  // meant N identical multi-KB copies per batch, permanently, in every subsequent turn's
  // wire payload and in Postgres. active/paused/failed nodes keep the full definition,
  // since Prompt: Form / Build SAP Payload / Prompt: Intention Focus all still need it.
  const storedDefinition = status === 'completed'
    ? { name: data.process_definition?.name ?? null }
    : data.process_definition;
  intentionNodes = {
    ...intentionNodes,
    [newNodeId]: {
      id: newNodeId,
      parent_id: data.parent_id ?? null,
      process_id: processId,
      process_definition: storedDefinition,
      form_state: data.form_state ?? {},
      status,
      error_detail: data.error_detail ?? null,
    },
  };
  return { data, newNodeId };
});
return registered.map(({ data, newNodeId }) => ({ json: {
  ...data,
  intention_nodes: intentionNodes,
  active_node_id: data.set_active ? newNodeId : data.active_node_id,
  new_node_id: newNodeId,
} }));
